import React, { useState } from 'react';
import { RegexDefinition } from '../types';

const RegexUploader: React.FC<{ onRegexUpload: (regexList: RegexDefinition[]) => void }> = ({ onRegexUpload }) => {
    const [file, setFile] = useState<File | null>(null);
    const [error, setError] = useState<string | null>(null);

    const isValidRegexDefinition = (value: any): value is RegexDefinition => {
        return (
            typeof value === 'object' &&
            value !== null &&
            typeof value.name === 'string' &&
            typeof value.pattern === 'string' &&
            Array.isArray(value.tags) &&
            value.tags.every((tag) => typeof tag === 'string')
        );
    };

    const parseRegexList = (parsed: any): RegexDefinition[] | null => {
        if (Array.isArray(parsed) && parsed.every(isValidRegexDefinition)) {
            return parsed;
        }

        if (typeof parsed === 'object' && parsed !== null) {
            const arrays = Object.values(parsed).filter(Array.isArray);
            for (const arr of arrays) {
                if (arr.every(isValidRegexDefinition)) {
                    return arr;
                }
            }
        }

        return null;
    };

    const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = event.target.files?.[0];
        if (selectedFile) {
            setFile(selectedFile);
            setError(null);
        }
    };

    const handleUpload = async () => {
        if (!file) {
            setError('Please select a file to upload.');
            return;
        }

        const reader = new FileReader();
        reader.onload = (e) => {
            const content = e.target?.result ? e.target.result.toString() : '';
            if (!content) {
                setError('The selected file is empty.');
                return;
            }
            try {
                const parsed = JSON.parse(content);
                const regexList = parseRegexList(parsed);
                if (!regexList) {
                    setError('Invalid JSON structure. Expect an array of regex definitions.');
                    return;
                }

                onRegexUpload(regexList);
                setFile(null);
                setError(null);
            } catch (err) {
                setError('Invalid file format. Please ensure it is a valid JSON file.');
            }
        };
        reader.readAsText(file);
    };

    return (
        <div>
            <input type="file" accept=".json" onChange={handleFileChange} />
            <button onClick={handleUpload}>Upload Regex</button>
            {error && <p style={{ color: 'red' }}>{error}</p>}
        </div>
    );
};

export default RegexUploader;
